#include <stdio.h>
#include <string.h>

#define CAPACITY 3
#define TTL 100

typedef struct {
    char key[32];
    int value;
    int stored_at;
    int used;
    long recency;
} Entry;

static Entry store[CAPACITY];
static long clock_counter = 0;

static int find_slot(const char *key) {
    for (int i = 0; i < CAPACITY; i++) {
        if (store[i].used && strcmp(store[i].key, key) == 0) return i;
    }
    return -1;
}

static void evict_lru(void) {
    int lru_idx = -1;
    long lru_recency = 0;
    for (int i = 0; i < CAPACITY; i++) {
        if (!store[i].used) { lru_idx = i; break; }
        if (lru_idx == -1 || store[i].recency < lru_recency) {
            lru_idx = i;
            lru_recency = store[i].recency;
        }
    }
    store[lru_idx].used = 0;
}

static void do_put(const char *key, int value, int now) {
    int idx = find_slot(key);
    if (idx == -1) {
        int free_idx = -1;
        for (int i = 0; i < CAPACITY; i++) {
            if (!store[i].used) { free_idx = i; break; }
        }
        if (free_idx == -1) {
            evict_lru();
            for (int i = 0; i < CAPACITY; i++) {
                if (!store[i].used) { free_idx = i; break; }
            }
        }
        idx = free_idx;
        strncpy(store[idx].key, key, 31);
        store[idx].key[31] = '\0';
        store[idx].used = 1;
    }
    store[idx].value = value;
    store[idx].stored_at = now;
    store[idx].recency = ++clock_counter;
}

static void do_get(const char *key, int now) {
    int idx = find_slot(key);
    if (idx == -1) { printf("MISS\n"); return; }
    if (now - store[idx].stored_at >= TTL) {
        store[idx].used = 0;
        printf("MISS\n");
        return;
    }
    store[idx].recency = ++clock_counter;
    printf("%d\n", store[idx].value);
}

int main(void) {
    char cmd[16], key[64];
    int value, now;
    while (scanf("%15s", cmd) == 1) {
        if (strcmp(cmd, "put") == 0) {
            if (scanf("%63s %d %d", key, &value, &now) == 3) do_put(key, value, now);
        } else if (strcmp(cmd, "get") == 0) {
            if (scanf("%63s %d", key, &now) == 2) do_get(key, now);
        }
    }
    return 0;
}

